<?php
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_role(['administrador','ventanilla']);
$pdo=db(); $errors=[];
$points=$pdo->query("SELECT id_punto,nombre,comuna FROM puntos_atencion WHERE estado='activo' ORDER BY nombre")->fetchAll();
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 $data=['nombres'=>trim($_POST['nombres']??''),'apellidos'=>trim($_POST['apellidos']??''),'celular'=>trim($_POST['celular']??''),'direccion'=>trim($_POST['direccion']??''),'barrio'=>trim($_POST['barrio']??''),'comuna'=>trim($_POST['comuna']??''),'corregimiento'=>trim($_POST['corregimiento']??''),'id_punto'=>(int)($_POST['id_punto']??0),'latitud'=>trim($_POST['latitud']??''),'longitud'=>trim($_POST['longitud']??'')];
 foreach(['nombres','apellidos','celular','direccion','barrio','comuna'] as $f) if($data[$f]==='') $errors[]='El campo '.str_replace('_',' ',$f).' es obligatorio.';
 if(!preg_match('/^[0-9+()\-\s]{7,20}$/',$data['celular'])) $errors[]='El número de celular no tiene un formato válido.';
 if($data['id_punto']<1) $errors[]='Selecciona el punto de atención.';
 if(!is_numeric($data['latitud']) || !is_numeric($data['longitud']) || (float)$data['latitud'] < -90 || (float)$data['latitud'] > 90 || (float)$data['longitud'] < -180 || (float)$data['longitud'] > 180) $errors[]='Selecciona la ubicación de la solicitud en el mapa.';
 if(!$errors){
  $stmt=$pdo->prepare('INSERT INTO solicitudes (id_usuario,id_punto,nombres,apellidos,celular,direccion,barrio,comuna,corregimiento,latitud,longitud,fecha_registro,estado) VALUES (?,?,?,?,?,?,?,?,?,?,?,NOW(),?)');
  $stmt->execute([current_user()['id'],$data['id_punto'],$data['nombres'],$data['apellidos'],$data['celular'],$data['direccion'],$data['barrio'],$data['comuna'],$data['corregimiento']?:null,(float)$data['latitud'],(float)$data['longitud'],'registrada']);
  $id=(int)$pdo->lastInsertId(); log_event($pdo,(int)current_user()['id'],'SOLICITUD_CREADA','Se registró la solicitud #'.$id.'.',$id);
  flash('success','Solicitud #'.$id.' registrada correctamente.'); redirect('solicitudes.php');
 }
}
$includeMap=true; $pageTitle='Registrar solicitud'; require __DIR__.'/includes/header.php';
?>
