foreach($points as $p): ?><option value="<?= (int)$p['id_punto'] ?>" <?= ((int)($_POST['id_punto']??0)===(int)$p['id_punto']?'selected':'') ?>><?= e($p['nombre'].' · '.$p['comuna']) ?></option><?php endforeach; ?></select></div></div></div></div>
